import {
  buildAcpHighlightLayers,
  callHighlightItems,
  OPERATION_LAYER_STYLES,
} from './acpHighlightLayers';
import type { AcpHighlightItem } from '../../../shared/main-process-api-interfaces/AcpAPI';

function items(count: number, operation: 'list' | 'read' = 'list') {
  return Array.from({ length: count }, (_, index) => ({
    path: `src/renderer/dir-${index}`,
    operation,
    kind: 'directory' as const,
  }));
}

describe('buildAcpHighlightLayers', () => {
  it('buckets directory listings into the Listings border layer', () => {
    const layers = buildAcpHighlightLayers([
      {
        status: 'completed',
        name: 'shell',
        kind: 'execute',
        highlightItems: [
          {
            path: 'src/renderer',
            operation: 'list',
            kind: 'directory',
          },
        ],
      },
    ]);

    expect(layers).toHaveLength(1);
    expect(layers[0]).toMatchObject({
      id: 'acp-operation-list',
      name: 'Listings',
      color: OPERATION_LAYER_STYLES.list.color,
      items: [
        {
          path: 'src/renderer',
          type: 'directory',
          renderStrategy: 'border',
        },
      ],
    });
  });

  it('caps each operation bucket to its newest items', () => {
    const layers = buildAcpHighlightLayers([
      { status: 'completed', highlightItems: items(25) },
    ]);

    expect(layers[0].items).toHaveLength(
      OPERATION_LAYER_STYLES.list.maxItems,
    );
    expect(layers[0].items?.[0].path).toBe('src/renderer/dir-0');
  });

  it('promotes a path to the strongest operation that touched it', () => {
    const layers = buildAcpHighlightLayers([
      {
        status: 'completed',
        highlightItems: [
          { path: 'src/renderer/App.tsx', operation: 'read', kind: 'file' },
        ],
      },
      {
        status: 'completed',
        highlightItems: [
          { path: 'src/renderer/App.tsx', operation: 'edit', kind: 'file' },
        ],
      },
    ]);

    expect(layers.map((layer) => layer.id)).toEqual(['acp-operation-edit']);
    expect(layers[0].items?.[0]).toMatchObject({
      path: 'src/renderer/App.tsx',
      renderStrategy: 'fill',
    });
  });

  it('marks paths from pending calls in the Active tool layer', () => {
    const layers = buildAcpHighlightLayers(
      [
        {
          status: 'in_progress',
          highlightItems: [
            { path: 'src/renderer/App.tsx', operation: 'read', kind: 'file' },
          ],
        },
      ],
      { activeColor: '#ff00aa' },
    );

    expect(layers.find((layer) => layer.id === 'acp-active-tool')).toMatchObject(
      {
        color: '#ff00aa',
        items: [
          {
            path: 'src/renderer/App.tsx',
            type: 'file',
            renderStrategy: 'border',
          },
        ],
      },
    );
  });

  it('falls back to highlightPaths using the call kind', () => {
    expect(
      callHighlightItems({
        kind: 'search',
        highlightPaths: ['src/main/acp', 'src/main/acp'],
      }),
    ).toEqual<AcpHighlightItem[]>([
      { path: 'src/main/acp', operation: 'search' },
    ]);
  });
});

import React, { useMemo, useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import {
  ThemeProvider,
  slateNeonTheme,
  useTheme,
} from '@principal-ade/industry-theme';
import {
  ArchitectureMapHighlightLayers,
  type CityData,
  type HighlightLayer,
} from '@principal-ai/file-city-react';
import { buildFileSystemTreeFromFileInfoList } from '@principal-ai/file-city-builder';
import type { AcpFileOperation } from '../../../shared/main-process-api-interfaces/AcpAPI';
import { buildCityDataFromFileTree } from '../file-city-panel/cityDataBuilders';
import {
  OPERATION_LAYER_STYLES,
  buildAcpHighlightLayers,
} from './acpHighlightLayers';
import corpusJson from './__fixtures__/acpHighlightCorpus.json';

/**
 * Audit surface for ACP tool call → File City highlight mapping.
 *
 * The fixture is generated by `scripts/collect-acp-highlight-corpus.mjs`,
 * which replays real OpenCode tool calls through the same
 * OpenCodeACPEventProcessor the event worker uses and applies the event
 * server's workspace-relative filter. That keeps this story free of Node-only
 * imports while still showing the extractor's real output.
 *
 * Regenerate the corpus after changing the extractor:
 *   node scripts/collect-acp-highlight-corpus.mjs
 */

interface CorpusIntent {
  path: string;
  operation: string;
  kind: 'file' | 'directory';
  source?: string;
}

interface CorpusCase {
  id: string;
  category: string;
  provenance: {
    sessionId: string;
    messageId: string;
    callId: string;
    createdAt: string;
  };
  tool: {
    name: string;
    kind: string;
    status: string;
    command?: string;
    rawInput?: Record<string, unknown>;
    locations?: Array<{ path: string }>;
    content?: string;
  };
  intents: CorpusIntent[];
  items: Array<{
    path: string;
    operation: string;
    kind: 'file' | 'directory';
  }>;
  dropped: Array<{ path: string; reason: string }>;
  outcome: 'highlighted' | 'no-file-paths' | 'error';
  error?: string;
}

interface Corpus {
  generatedAt: string;
  workspace: string;
  appCommit: string;
  agentMonitoringVersion: string;
  source: {
    kind: string;
    path: string;
    sessionsScanned: number;
    toolCallsScanned: number;
    note: string;
  };
  cityFiles: string[];
  cases: CorpusCase[];
}

const corpus = corpusJson as unknown as Corpus;
const cases = corpus.cases;

const cityData: CityData = buildCityDataFromFileTree(
  buildFileSystemTreeFromFileInfoList(
    corpus.cityFiles.map((path) => {
      const name = path.split('/').pop() ?? path;
      return {
        path,
        name,
        extension: name.includes('.') ? (name.split('.').pop() ?? '') : '',
        size: 120,
        lastModified: new Date(0),
        isDirectory: false,
        relativePath: path,
      };
    }),
    'acp-highlight-corpus',
  ),
  '',
);

function caseLabel(item: CorpusCase): string {
  return item.tool.command ?? `${item.tool.name} ${item.tool.kind}`;
}

function layersForCase(item: CorpusCase): HighlightLayer[] {
  return buildAcpHighlightLayers([
    {
      status: 'completed',
      name: item.tool.name,
      kind: item.tool.kind,
      highlightItems: item.items.map((entry) => ({
        path: entry.path,
        operation: entry.operation as AcpFileOperation,
        kind: entry.kind,
      })),
    },
  ]);
}

function cityHasPath(
  path: string,
  kind: 'file' | 'directory',
): boolean {
  if (kind === 'directory') {
    return cityData.districts.some((district) => district.path === path);
  }
  return cityData.buildings.some((building) => building.path === path);
}

function formatDate(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toISOString().slice(0, 10);
}

const mono: React.CSSProperties = {
  fontFamily:
    'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
};

function OperationChip({
  operation,
  count,
}: {
  operation: AcpFileOperation;
  count?: number;
}) {
  const style =
    OPERATION_LAYER_STYLES[operation] ??
    OPERATION_LAYER_STYLES.execute;
  return (
    <span
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 6,
        padding: '2px 7px',
        borderRadius: 999,
        border: `1px solid ${style.color}`,
        color: style.color,
        background: `${style.color}14`,
        fontSize: 11,
        fontVariantNumeric: 'tabular-nums',
        whiteSpace: 'nowrap',
      }}
    >
      <span
        style={{
          width: 7,
          height: 7,
          borderRadius: 999,
          background: style.color,
        }}
      />
      {style.label}
      {typeof count === 'number' ? ` · ${count}` : ''}
    </span>
  );
}

function StatusBadge({ item }: { item: CorpusCase }) {
  const { theme } = useTheme();
  const color =
    item.outcome === 'highlighted'
      ? theme.colors.success ?? '#22c55e'
      : theme.colors.warning ?? '#f59e0b';
  return (
    <span
      style={{
        ...mono,
        fontSize: 10,
        letterSpacing: 0.4,
        textTransform: 'uppercase',
        color,
        border: `1px solid ${color}`,
        borderRadius: 4,
        padding: '1px 5px',
      }}
    >
      {item.outcome}
    </span>
  );
}

function CaseList({
  selectedId,
  onSelect,
}: {
  selectedId: string;
  onSelect: (id: string) => void;
}) {
  const { theme } = useTheme();
  const [query, setQuery] = useState('');
  const categories = useMemo(
    () => [...new Set(cases.map((item) => item.category))].sort(),
    [],
  );
  const [category, setCategory] = useState('all');

  const visible = cases.filter((item) => {
    if (category !== 'all' && item.category !== category) return false;
    if (!query.trim()) return true;
    return caseLabel(item).toLowerCase().includes(query.toLowerCase());
  });

  return (
    <aside
      style={{
        width: 340,
        minWidth: 300,
        borderRight: `1px solid ${theme.colors.border}`,
        display: 'flex',
        flexDirection: 'column',
        minHeight: 0,
      }}
    >
      <div
        style={{
          padding: 12,
          borderBottom: `1px solid ${theme.colors.border}`,
          display: 'grid',
          gap: 8,
        }}
      >
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Filter commands…"
          style={{
            width: '100%',
            padding: '6px 8px',
            borderRadius: 6,
            border: `1px solid ${theme.colors.border}`,
            background: theme.colors.backgroundSecondary,
            color: theme.colors.text,
            fontSize: 12,
          }}
        />
        <select
          value={category}
          onChange={(event) => setCategory(event.target.value)}
          style={{
            width: '100%',
            padding: '6px 8px',
            borderRadius: 6,
            border: `1px solid ${theme.colors.border}`,
            background: theme.colors.backgroundSecondary,
            color: theme.colors.text,
            fontSize: 12,
          }}
        >
          <option value="all">All categories ({cases.length})</option>
          {categories.map((value) => (
            <option key={value} value={value}>
              {value} ({cases.filter((item) => item.category === value).length})
            </option>
          ))}
        </select>
      </div>
      <ol
        style={{
          listStyle: 'none',
          margin: 0,
          padding: 0,
          overflowY: 'auto',
          minHeight: 0,
        }}
      >
        {visible.map((item) => {
          const selected = item.id === selectedId;
          return (
            <li key={item.id}>
              <button
                type="button"
                onClick={() => onSelect(item.id)}
                style={{
                  display: 'grid',
                  gap: 5,
                  width: '100%',
                  textAlign: 'left',
                  padding: '9px 12px',
                  border: 0,
                  borderBottom: `1px solid ${theme.colors.border}`,
                  borderLeft: `3px solid ${
                    selected ? theme.colors.primary : 'transparent'
                  }`,
                  background: selected
                    ? theme.colors.backgroundSecondary
                    : 'transparent',
                  color: theme.colors.text,
                  cursor: 'pointer',
                }}
              >
                <span
                  style={{
                    ...mono,
                    fontSize: 11.5,
                    lineHeight: 1.35,
                    overflow: 'hidden',
                    display: '-webkit-box',
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: 'vertical',
                  }}
                >
                  {caseLabel(item)}
                </span>
                <span
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 6,
                    flexWrap: 'wrap',
                  }}
                >
                  <StatusBadge item={item} />
                  <span
                    style={{
                      fontSize: 10.5,
                      color: theme.colors.textSecondary,
                    }}
                  >
                    {item.intents.length} intent
                    {item.intents.length === 1 ? '' : 's'}
                    {item.dropped.length > 0
                      ? ` · ${item.dropped.length} dropped`
                      : ''}
                  </span>
                </span>
              </button>
            </li>
          );
        })}
      </ol>
    </aside>
  );
}

function IntentTable({ item }: { item: CorpusCase }) {
  const { theme } = useTheme();
  return (
    <div style={{ overflowX: 'auto' }}>
      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          fontSize: 11.5,
        }}
      >
        <thead>
          <tr style={{ color: theme.colors.textSecondary }}>
            {['Operation', 'Kind', 'Source', 'Path', 'City'].map((label) => (
              <th
                key={label}
                style={{
                  textAlign: 'left',
                  fontWeight: 500,
                  padding: '6px 8px',
                  borderBottom: `1px solid ${theme.colors.border}`,
                  whiteSpace: 'nowrap',
                }}
              >
                {label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {item.intents.map((intent, index) => {
            const operation = intent.operation as AcpFileOperation;
            const inCity = cityHasPath(intent.path, intent.kind);
            return (
              <tr key={`${intent.path}-${index}`}>
                <td
                  style={{
                    padding: '6px 8px',
                    borderBottom: `1px solid ${theme.colors.border}`,
                  }}
                >
                  <OperationChip operation={operation} />
                </td>
                <td
                  style={{
                    padding: '6px 8px',
                    borderBottom: `1px solid ${theme.colors.border}`,
                    color: theme.colors.textSecondary,
                  }}
                >
                  {intent.kind}
                </td>
                <td
                  style={{
                    padding: '6px 8px',
                    borderBottom: `1px solid ${theme.colors.border}`,
                    color: theme.colors.textSecondary,
                  }}
                >
                  {intent.source ?? '—'}
                </td>
                <td
                  style={{
                    ...mono,
                    padding: '6px 8px',
                    borderBottom: `1px solid ${theme.colors.border}`,
                    wordBreak: 'break-all',
                  }}
                >
                  {intent.path}
                </td>
                <td
                  style={{
                    padding: '6px 8px',
                    borderBottom: `1px solid ${theme.colors.border}`,
                    color: inCity
                      ? (theme.colors.success ?? '#22c55e')
                      : (theme.colors.warning ?? '#f59e0b'),
                    whiteSpace: 'nowrap',
                  }}
                >
                  {inCity ? 'present' : 'missing'}
                </td>
              </tr>
            );
          })}
          {item.intents.length === 0 ? (
            <tr>
              <td
                colSpan={5}
                style={{
                  padding: '10px 8px',
                  color: theme.colors.textSecondary,
                }}
              >
                No intents extracted. The call produces no highlight.
              </td>
            </tr>
          ) : null}
        </tbody>
      </table>
    </div>
  );
}

